          body: 'Varlikent ("wir", "uns", "unser") betreibt diese Website und die darauf angebotenen Dienste, einschließlich Immobilienanzeigen, unseres KI-Chat-Assistenten und der Weiterleitung von Interessenten an unsere Vertreter und Partner. Diese Datenschutzerklärung erläutert, welche Informationen wir sammeln, warum wir sie sammeln, wie wir sie nutzen und schützen und welche Wahlmöglichkeiten Sie haben. Mit der Nutzung dieser Website erklären Sie sich mit den hier beschriebenen Praktiken einverstanden.',
