          body: 'Varlikent («мы», «нас», «наш») управляет этим сайтом и предоставляемыми на нём услугами, включая объявления о недвижимости, нашего ИИ-чат-ассистента и маршрутизацию заявок к нашим агентам и партнёрам. Эта Политика конфиденциальности объясняет, какую информацию мы собираем, зачем мы её собираем, как мы её используем и защищаем, а также какие у вас есть возможности выбора. Используя этот сайт, вы соглашаетесь с описанными здесь практиками.',
